  async flushToClearcut() {
    if (this.flushing) {
      if (this.config?.getDebugMode()) {
        debugLogger.debug(
          "ClearcutLogger: Flush already in progress, marking pending flush."
        );
      }
      this.pendingFlush = true;
      return Promise.resolve({});
    }
    this.flushing = true;
    if (this.config?.getDebugMode()) {
      debugLogger.log("Flushing log events to Clearcut.");
    }
    const eventsToSend = this.events.toArray();
    this.events.clear();
    const request = [
      {
        log_source_name: "CONCORD",
        request_time_ms: Date.now(),
        log_event: eventsToSend
      }
    ];
    let result2 = {};
    try {
      const response = await fetch(CLEARCUT_URL, {
        method: "POST",
        body: safeJsonStringify(request),
        headers: {
          "Content-Type": "application/json"
        }
      });
      const responseBody = await response.text();
      if (response.status >= 200 && response.status < 300) {
        this.lastFlushTime = Date.now();
        const nextRequestWaitMs = Number(JSON.parse(responseBody)[0]);
        result2 = {
          ...result2,
          nextRequestWaitMs
        };
      } else {
        if (this.config?.getDebugMode()) {
          debugLogger.warn(
            `Error flushing log events: HTTP ${response.status}: ${response.statusText}`
          );
        }
        this.requeueFailedEvents(eventsToSend);
      }
    } catch (e2) {
      if (this.config?.getDebugMode()) {
        debugLogger.warn("Error flushing log events:", e2);
      }
      this.requeueFailedEvents(eventsToSend);
    }
    this.flushing = false;
    if (this.pendingFlush) {
      this.pendingFlush = false;
      this.flushToClearcut().catch((error40) => {
        if (this.config?.getDebugMode()) {
          debugLogger.debug("Error in pending flush to Clearcut:", error40);
        }
      });
    }
    return result2;
  }
