// packages/core/src/scheduler/hook-utils.ts
async function evaluateBeforeToolHook(config2, tool, request, invocation) {
  const hookSystem = config2.getHookSystem();
  if (!hookSystem) {
    return { status: "continue" };
  }
  const params = invocation.params || {};
  const toolInput = { ...params };
  const mcpContext = extractMcpContext(invocation, config2);
  const beforeOutput = await hookSystem.fireBeforeToolEvent(
    request.name,
    toolInput,
    mcpContext,
    request.originalRequestName
  );
  if (!beforeOutput) {
    return { status: "continue" };
  }
  if (beforeOutput.shouldStopExecution()) {
    return {
      status: "error",
      error: new Error(
        `Agent execution stopped by hook: ${beforeOutput.getEffectiveReason()}`
      ),
      errorType: "stop_execution" /* STOP_EXECUTION */
    };
  }
  const blockingError = beforeOutput.getBlockingError();
  if (blockingError?.blocked) {
    return {
      status: "error",
      error: new Error(`Tool execution blocked: ${blockingError.reason}`),
      errorType: "policy_violation" /* POLICY_VIOLATION */
    };
  }
  let hookDecision;
  let hookSystemMessage;
  if (beforeOutput.isAskDecision()) {
    hookDecision = "ask";
    hookSystemMessage = beforeOutput.systemMessage;
  }
  let modifiedArgs;
  let newInvocation;
  if (beforeOutput instanceof BeforeToolHookOutput) {
    const modifiedInput = beforeOutput.getModifiedToolInput();
    if (modifiedInput) {
      modifiedArgs = modifiedInput;
      try {
        newInvocation = tool.build(modifiedInput);
      } catch (error40) {
        return {
          status: "error",
          error: new Error(
            `Tool parameter modification by hook failed validation: ${error40 instanceof Error ? error40.message : String(error40)}`
          ),
          errorType: "invalid_tool_params" /* INVALID_TOOL_PARAMS */
        };
      }
    }
  }
  return {
    status: "continue",
    hookDecision,
    hookSystemMessage,
    modifiedArgs,
    newInvocation
  };
}

// packages/core/src/utils/nextSpeakerChecker.ts
var CHECK_PROMPT = `Analyze *only* the content and structure of your immediately preceding response (your last turn in the conversation history). Based *strictly* on that response, determine who should logically speak next: the 'user' or the 'model' (you).
**Decision Rules (apply in order):**
1.  **Model Continues:** If your last response explicitly states an immediate next action *you* intend to take (e.g., "Next, I will...", "Now I'll process...", "Moving on to analyze...", indicates an intended tool call that didn't execute), OR if the response seems clearly incomplete (cut off mid-thought without a natural conclusion), then the **'model'** should speak next.
2.  **Question to User:** If your last response ends with a direct question specifically addressed *to the user*, then the **'user'** should speak next.
3.  **Waiting for User:** If your last response completed a thought, statement, or task *and* does not meet the criteria for Rule 1 (Model Continues) or Rule 2 (Question to User), it implies a pause expecting user input or reaction. In this case, the **'user'** should speak next.`;
var RESPONSE_SCHEMA = {
  type: "object",
  properties: {
    reasoning: {
      type: "string",
      description: "Brief explanation justifying the 'next_speaker' choice based *strictly* on the applicable rule and the content/structure of the preceding turn."
    },
    next_speaker: {
      type: "string",
      enum: ["user", "model"],
      description: "Who should speak next based *only* on the preceding turn and the decision rules"
    }
  },
  required: ["reasoning", "next_speaker"]
};
async function checkNextSpeaker(chat, baseLlmClient, abortSignal, promptId) {
  const curatedHistory = chat.getHistory(
    /* curated */
    true
  );
  if (curatedHistory.length === 0) {
    return null;
  }
  const comprehensiveHistory = chat.getHistory();
  if (comprehensiveHistory.length === 0) {
    return null;
  }
  const lastComprehensiveMessage = comprehensiveHistory[comprehensiveHistory.length - 1];
  if (lastComprehensiveMessage && isFunctionResponse(lastComprehensiveMessage)) {
    return {
      reasoning: "The last message was a function response, so the model should speak next.",
      next_speaker: "model"
    };
  }
  if (lastComprehensiveMessage && lastComprehensiveMessage.role === "model" && lastComprehensiveMessage.parts && lastComprehensiveMessage.parts.length === 0) {
    return {
      reasoning: "The last message was a filler model message with no content (nothing for user to act on), model should speak next.",
      next_speaker: "model"
    };
  }
  const lastMessage = curatedHistory[curatedHistory.length - 1];
  if (!lastMessage || lastMessage.role !== "model") {
    return null;
  }
  const contents = [
    ...curatedHistory,
    { role: "user", parts: [{ text: CHECK_PROMPT }] }
  ];
  try {
    const parsedResponse = await baseLlmClient.generateJson({
      modelConfigKey: { model: "next-speaker-checker" },
      contents,
      schema: RESPONSE_SCHEMA,
      abortSignal,
      promptId,
      role: "utility_next_speaker" /* UTILITY_NEXT_SPEAKER */
    });
    if (parsedResponse && parsedResponse.next_speaker && ["user", "model"].includes(parsedResponse.next_speaker)) {
      return parsedResponse;
    }
    return null;
  } catch (error40) {
    debugLogger.warn(
      "Failed to talk to Gemini endpoint when seeing if conversation should continue.",
      error40
    );
    return null;
  }
}

