// packages/core/src/routing/strategies/compositeStrategy.ts
var CompositeStrategy = class {
  name;
  strategies;
  /**
   * Initializes the CompositeStrategy.
   * @param strategies The strategies to try, in order of priority. The last strategy must be terminal.
   * @param name The name of this composite configuration (e.g., 'router' or 'composite').
   */
  constructor(strategies, name3 = "composite") {
    this.strategies = strategies;
    this.name = name3;
  }
  async route(context2, config2, baseLlmClient, localLiteRtLmClient) {
    const startTime = performance.now();
    const nonTerminalStrategies = this.strategies.slice(
      0,
      -1
    );
    const terminalStrategy = this.strategies[this.strategies.length - 1];
    for (const strategy of nonTerminalStrategies) {
      try {
        const decision = await strategy.route(
          context2,
          config2,
          baseLlmClient,
          localLiteRtLmClient
        );
        if (decision) {
          return this.finalizeDecision(decision, startTime);
        }
      } catch (error40) {
        debugLogger.warn(
          `[Routing] Strategy '${strategy.name}' failed. Continuing to next strategy. Error:`,
          error40
        );
      }
    }
    try {
      const decision = await terminalStrategy.route(
        context2,
        config2,
        baseLlmClient,
        localLiteRtLmClient
      );
      return this.finalizeDecision(decision, startTime);
    } catch (error40) {
      coreEvents.emitFeedback(
        "error",
        `[Routing] Critical Error: Terminal strategy '${terminalStrategy.name}' failed. Routing cannot proceed. Error:`,
        error40
      );
      throw error40;
    }
  }
  /**
   * Helper function to enhance the decision metadata with composite information.
   */
  finalizeDecision(decision, startTime) {
    const endTime = performance.now();
    const compositeSource = `${this.name}/${decision.metadata.source}`;
    const latency = decision.metadata.latencyMs || endTime - startTime;
    return {
      ...decision,
      metadata: {
        ...decision.metadata,
        source: compositeSource,
        latencyMs: Math.round(latency)
        // Round to ensure int for telemetry.
      }
    };
  }
};

// packages/core/src/routing/strategies/fallbackStrategy.ts
var FallbackStrategy = class {
  name = "fallback";
  async route(context2, config2, _baseLlmClient, _localLiteRtLmClient) {
    const requestedModel = context2.requestedModel ?? config2.getModel();
    const resolvedModel = resolveModel(
      requestedModel,
      config2.getGemini31LaunchedSync?.() ?? false,
      config2.getGemini31FlashLiteLaunchedSync?.() ?? false,
      false,
      config2.getHasAccessToPreviewModel?.() ?? true,
      config2
    );
    const service = config2.getModelAvailabilityService();
    const snapshot = service.snapshot(resolvedModel);
    if (snapshot.available) {
      return null;
    }
    const selection = selectModelForAvailability(config2, requestedModel);
    if (selection?.selectedModel && selection.selectedModel !== requestedModel) {
      return {
        model: selection.selectedModel,
        metadata: {
          source: this.name,
          latencyMs: 0,
          reasoning: `Model ${requestedModel} is unavailable (${snapshot.reason}). Using fallback: ${selection.selectedModel}`
        }
      };
    }
    return null;
  }
};

