// packages/core/src/routing/strategies/approvalModeStrategy.ts
var ApprovalModeStrategy = class {
  name = "approval-mode";
  async route(context2, config2, _baseLlmClient) {
    const model = context2.requestedModel ?? config2.getModel();
    if (!isAutoModel(model, config2)) {
      return null;
    }
    if (!await config2.getPlanModeRoutingEnabled()) {
      return null;
    }
    const startTime = Date.now();
    const approvalMode = config2.getApprovalMode();
    const approvedPlanPath = config2.getApprovedPlanPath();
    const [
      useGemini3_1,
      useGemini3_1FlashLite,
      useCustomToolModel,
      hasAccessToPreview
    ] = await Promise.all([
      config2.getGemini31Launched(),
      config2.getGemini31FlashLiteLaunched(),
      config2.getUseCustomToolModel(),
      config2.getHasAccessToPreviewModel()
    ]);
    if (approvalMode === "plan" /* PLAN */) {
      const proModel = resolveClassifierModel(
        model,
        GEMINI_MODEL_ALIAS_PRO,
        useGemini3_1,
        useGemini3_1FlashLite,
        useCustomToolModel,
        hasAccessToPreview,
        config2
      );
      return {
        model: proModel,
        metadata: {
          source: this.name,
          latencyMs: Date.now() - startTime,
          reasoning: "Routing to Pro model because ApprovalMode is PLAN."
        }
      };
    } else if (approvedPlanPath) {
      const flashModel = resolveClassifierModel(
        model,
        GEMINI_MODEL_ALIAS_FLASH,
        useGemini3_1,
        useGemini3_1FlashLite,
        useCustomToolModel,
        hasAccessToPreview,
        config2
      );
      return {
        model: flashModel,
        metadata: {
          source: this.name,
          latencyMs: Date.now() - startTime,
          reasoning: `Routing to Flash model because an approved plan exists at ${approvedPlanPath}.`
        }
      };
    }
    return null;
  }
};

// packages/core/src/routing/modelRouterService.ts
var ModelRouterService = class {
  config;
  strategy;
  constructor(config2) {
    this.config = config2;
    this.strategy = this.initializeDefaultStrategy();
  }
  initializeDefaultStrategy() {
    const strategies = [];
    strategies.push(new FallbackStrategy());
    strategies.push(new OverrideStrategy());
    strategies.push(new ApprovalModeStrategy());
    if (this.config.getGemmaModelRouterSettings()?.enabled) {
      strategies.push(new GemmaClassifierStrategy());
    }
    strategies.push(new ClassifierStrategy());
    strategies.push(new NumericalClassifierStrategy());
    const terminalStrategy = new DefaultStrategy();
    return new CompositeStrategy(
      [...strategies, terminalStrategy],
      "agent-router"
    );
  }
  /**
   * Determines which model to use for a given request context.
   *
   * @param context The full context of the request.
   * @returns A promise that resolves to a RoutingDecision.
   */
  async route(context2) {
    const startTime = Date.now();
    let decision;
    const [enableNumericalRouting, thresholdValue] = await Promise.all([
      this.config.getNumericalRoutingEnabled(),
      this.config.getResolvedClassifierThreshold()
    ]);
    const classifierThreshold = String(thresholdValue);
    let failed = false;
    let error_message;
    try {
      decision = await this.strategy.route(
        context2,
        this.config,
        this.config.getBaseLlmClient(),
        this.config.getLocalLiteRtLmClient()
      );
      debugLogger.debug(
        `[Routing] Selected model: ${decision.model} (Source: ${decision.metadata.source}, Latency: ${decision.metadata.latencyMs}ms)
	[Routing] Reasoning: ${decision.metadata.reasoning}`
      );
    } catch (e2) {
      failed = true;
      error_message = e2 instanceof Error ? e2.message : String(e2);
      decision = {
        model: this.config.getModel(),
        metadata: {
          source: "router-exception",
          latencyMs: Date.now() - startTime,
          reasoning: "An exception occurred during routing.",
          error: error_message
        }
      };
      debugLogger.debug(
        `[Routing] Exception during routing: ${error_message}
	Fallback model: ${decision.model} (Source: ${decision.metadata.source})`
      );
    } finally {
      const event = new ModelRoutingEvent(
        decision?.model || "unknown",
        decision?.metadata?.source || "unknown",
        decision?.metadata?.latencyMs || 0,
        decision?.metadata?.reasoning,
        failed,
        error_message,
        this.config.getApprovalMode(),
        enableNumericalRouting,
        classifierThreshold
      );
      logModelRouting(this.config, event);
    }
    return decision;
  }
};

