// packages/core/src/utils/pathReader.ts
import { promises as fs83 } from "node:fs";
import path100 from "node:path";
async function readPathFromWorkspace(pathStr, config2) {
  const workspace = config2.getWorkspaceContext();
  const fileService = config2.getFileService();
  let absolutePath = null;
  if (path100.isAbsolute(pathStr)) {
    if (!workspace.isPathWithinWorkspace(pathStr)) {
      throw new Error(
        `Absolute path is outside of the allowed workspace: ${pathStr}`
      );
    }
    absolutePath = pathStr;
  } else {
    const searchDirs = workspace.getDirectories();
    for (const dir of searchDirs) {
      const potentialPath = path100.resolve(dir, pathStr);
      try {
        await fs83.access(potentialPath);
        absolutePath = potentialPath;
        break;
      } catch {
      }
    }
  }
  if (!absolutePath) {
    throw new Error(`Path not found in workspace: ${pathStr}`);
  }
  const stats = await fs83.stat(absolutePath);
  if (stats.isDirectory()) {
    const allParts = [];
    allParts.push({
      text: `--- Start of content for directory: ${pathStr} ---
`
    });
    const files = await glob("**/*", {
      cwd: absolutePath,
      nodir: true,
      // We only want files
      dot: true,
      // Include dotfiles
      absolute: true
    });
    const relativeFiles = files.map(
      (p) => path100.relative(config2.getTargetDir(), p)
    );
    const filteredFiles = fileService.filterFiles(relativeFiles, {
      respectGitIgnore: config2.getFileFilteringRespectGitIgnore(),
      respectGeminiIgnore: config2.getFileFilteringRespectGeminiIgnore()
    });
    const finalFiles = filteredFiles.map(
      (p) => path100.resolve(config2.getTargetDir(), p)
    );
    for (const filePath of finalFiles) {
      const relativePathForDisplay = path100.relative(absolutePath, filePath);
      allParts.push({ text: `--- ${relativePathForDisplay} ---
` });
      const result2 = await processSingleFileContent(
        filePath,
        config2.getTargetDir(),
        config2.getFileSystemService()
      );
      allParts.push(result2.llmContent);
      allParts.push({ text: "\n" });
    }
    allParts.push({ text: `--- End of content for directory: ${pathStr} ---` });
    return allParts;
  } else {
    const relativePath = path100.relative(config2.getTargetDir(), absolutePath);
    const filtered = fileService.filterFiles([relativePath], {
      respectGitIgnore: config2.getFileFilteringRespectGitIgnore(),
      respectGeminiIgnore: config2.getFileFilteringRespectGeminiIgnore()
    });
    if (filtered.length === 0) {
      return [];
    }
    const result2 = await processSingleFileContent(
      absolutePath,
      config2.getTargetDir(),
      config2.getFileSystemService()
    );
    return [result2.llmContent];
  }
}

